import * as THREE from './vendor/three.module.js';
const ink=0x35566a,teal=0x328b84,gold=0xd49652,blue=0x558ab5,red=0xc97964;
function group(l){let g=new THREE.Group();l.world.add(g);return g;}
function sphere(l,r,color,x,y,z,parent=l.world){return l.mesh(new THREE.SphereGeometry(r,32,24),l.material(color,.25,.2),x,y,z,parent);}
function line(l,points,color=teal,parent=l.world,dashed=false){let g=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p)));let m=dashed?new THREE.LineDashedMaterial({color,dashSize:.1,gapSize:.08}):new THREE.LineBasicMaterial({color});let o=new THREE.Line(g,m);if(dashed)o.computeLineDistances();parent.add(o);return o;}
function setLine(o,points){o.geometry.dispose();o.geometry=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(...p)));if(o.material.isLineDashedMaterial)o.computeLineDistances();}
function arrow(l,origin,direction,length,color){let a=new THREE.ArrowHelper(new THREE.Vector3(...direction).normalize(),new THREE.Vector3(...origin),length,color,.15,.08);l.world.add(a);return a;}
function track(l){for(let z of[-.43,.43])l.box(7.6,.08,.06,0x879ba0,0,.4,z);for(let x=-3.5;x<=3.5;x+=.5)l.box(.015,.012,.16,0xa2b1ab,x,.13,.95);}
function cart(l,color){let g=group(l);l.box(.75,.33,.72,color,0,.38,0,g);for(let x of[-.25,.25])for(let z of[-.4,.4]){let wheel=l.cylinder(.13,.13,.09,ink,x,.18,z,g);wheel.rotation.x=Math.PI/2;}return g;}
function banner(l,text,x,y,z=0){l.plaque(text,1,.4,x,y,z);}
